"""The audit: a list of findings about a channel, each with its evidence and its caveats.

Rules the findings follow:
* Numbers are computed here, deterministically. Nothing is generated by a language model.
* A blank (not reported) is never treated as 0. A video with no impressions is left out of a click-rate comparison.
* A finding with too little data says so instead of reporting a number.
* Every comparison gives sample sizes and an interval, not only a p-value.
"""
import math
from dataclasses import asdict, dataclass, field
from datetime import date

import numpy as np
import pandas as pd

from audit.stats import Comparison, compare, log_linear_fit

SHORT_MAX_SECONDS = 60  # Studio's export has no "is a Short" flag, so duration is the proxy (documented limitation)
MIN_VIDEOS = 8  # fewer than this and most analyses are not attempted
TOO_NEW_DAYS = 14  # a video younger than this has not collected its views yet and is not judged

VIEWS, IMPRESSIONS, CTR = "Views", "Impressions", "Impressions click-through rate (%)"
RETENTION = "Average percentage viewed (%)"
ID, TITLE, PUBLISHED, DURATION = "Content", "Video title", "Video publish time", "Duration"


@dataclass
class Finding:
    key: str
    title: str
    headline: str
    strength: str  # how far to trust the headline: solid | suggestive | weak | not_enough_data | info
    details: dict = field(default_factory=dict)
    caveats: list[str] = field(default_factory=list)


@dataclass(frozen=True)
class Context:
    frame: pd.DataFrame  # one row per video; blanks are NaN
    totals: dict[str, float]  # the export's Total row
    as_of: date  # the date "now" means for video ages
    period_kind: str  # unknown | lifetime | range


def _num(frame: pd.DataFrame, column: str) -> pd.Series:
    return pd.to_numeric(frame[column], errors="coerce") if column in frame else pd.Series(np.nan, index=frame.index)


def _fmt(value: float) -> str:
    return f"{value:,.0f}" if abs(value) >= 100 else f"{value:,.1f}"


def _video(row: pd.Series, **extra) -> dict:
    return {"video_id": row[ID], "title": row.get(TITLE) or "", **extra}


# ── findings ────────────────────────────────────────────────────────────────


def overview(ctx: Context) -> Finding:
    views = _num(ctx.frame, VIEWS).dropna()
    caveats = []
    if views.empty:
        return Finding("overview", "Overview", "The export has no view counts.", "not_enough_data")
    ordered = views.sort_values(ascending=False)
    top_n = max(1, math.ceil(len(ordered) * 0.1))
    top_share = float(ordered.head(top_n).sum() / ordered.sum())
    total = ctx.totals.get(VIEWS)
    if total and total > ordered.sum() * 1.05:
        caveats.append(
            f"The export's Total ({_fmt(total)} views) is higher than the listed videos add up to "
            f"({_fmt(ordered.sum())}): it can include deleted videos and activity not credited to a video."
        )
    headline = (
        f"{len(views)} videos with a median of {_fmt(views.median())} views. "
        f"The top {top_n} ({top_n / len(views):.0%}) account for {top_share:.0%} of the listed views."
    )
    return Finding("overview", "Overview", headline, "info", {
        "videos": len(views), "median_views": float(views.median()), "mean_views": float(views.mean()),
        "total_views": float(total) if total else float(ordered.sum()),
        "top_decile_videos": top_n, "top_decile_share": top_share,
    }, caveats)


def performance(ctx: Context) -> Finding:
    """Views compared with what a video of that age usually has, so old videos do not win just by being old."""
    frame = ctx.frame.copy()
    frame["views"] = _num(frame, VIEWS)
    frame["age"] = (pd.Timestamp(ctx.as_of) - pd.to_datetime(frame[PUBLISHED], errors="coerce")).dt.days
    usable = frame.dropna(subset=["views", "age"])
    usable = usable[usable["age"] >= 0]
    if len(usable) < MIN_VIDEOS:
        return Finding("performance", "Standout videos", f"Needs at least {MIN_VIDEOS} dated videos; this export has "
                       f"{len(usable)}.", "not_enough_data")

    fit_rows = usable[usable["age"] >= TOO_NEW_DAYS]
    if len(fit_rows) < MIN_VIDEOS:
        return Finding("performance", "Standout videos", "Most videos are too new to judge.", "not_enough_data")
    slope, intercept, r2 = log_linear_fit(fit_rows["age"], fit_rows["views"])
    expected = 10 ** (slope * np.log10(fit_rows["age"] + 1) + intercept) - 1
    scored = fit_rows.assign(expected=expected, index=fit_rows["views"] / expected.clip(lower=1))

    def rows(frame_):
        return [
            _video(r, views=float(r["views"]), expected=float(r["expected"]), index=float(r["index"]),
                   age_days=int(r["age"]))
            for _, r in frame_.iterrows()
        ]

    best = scored.sort_values("index", ascending=False).head(5)
    worst = scored.sort_values("index").head(5)
    caveats = [
        f"Videos younger than {TOO_NEW_DAYS} days are not judged. "
        f"Age explains {r2:.0%} of the differences in views here; the rest is what the index shows.",
    ]
    if ctx.period_kind != "lifetime":
        caveats.append(
            "This export is not confirmed as lifetime figures. If it covers a date range, older videos only show "
            "the views inside that range and the index is less reliable."
        )
    top = best.iloc[0]
    return Finding(
        "performance", "Standout videos",
        f"\"{top[TITLE] or top[ID]}\" has {top['index']:.1f}x the views typical for its age. "
        f"{int((scored['index'] >= 2).sum())} videos are at least 2x typical; "
        f"{int((scored['index'] <= 0.5).sum())} are at half or less.",
        "suggestive" if len(scored) >= 20 else "weak",
        {"best": rows(best), "worst": rows(worst), "age_slope": slope, "age_r_squared": r2, "judged": len(scored)},
        caveats,
    )


def cadence(ctx: Context) -> Finding:
    dates = pd.to_datetime(ctx.frame[PUBLISHED], errors="coerce").dropna().sort_values()
    if len(dates) < MIN_VIDEOS:
        return Finding("cadence", "Upload rhythm", f"Needs at least {MIN_VIDEOS} dated videos.", "not_enough_data")

    as_of = pd.Timestamp(ctx.as_of)
    gaps = dates.diff().dt.days.dropna()
    longest = int(gaps.max())
    longest_end = dates[gaps.idxmax()]
    recent = int((dates > as_of - pd.Timedelta(days=90)).sum())
    before = int(((dates <= as_of - pd.Timedelta(days=90)) & (dates > as_of - pd.Timedelta(days=180))).sum())
    months = dates[dates > as_of - pd.Timedelta(days=365)].dt.to_period("M").value_counts().sort_index()
    weekdays = dates.dt.day_name().value_counts().reindex(
        ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"], fill_value=0
    )
    per_month = len(dates) / max((as_of - dates.iloc[0]).days / 30.44, 1)
    trend = "faster" if recent > before * 1.25 else "slower" if recent < before * 0.75 else "about the same"
    return Finding(
        "cadence", "Upload rhythm",
        f"About {per_month:.1f} uploads a month over the channel's life. The last 90 days had {recent} uploads against "
        f"{before} in the 90 days before: {trend}. The longest silence was {longest} days, ending "
        f"{longest_end:%b %d, %Y}.",
        "info",
        {"uploads_per_month": per_month, "last_90_days": recent, "previous_90_days": before,
         "longest_gap_days": longest, "longest_gap_ended": longest_end.date().isoformat(),
         "median_gap_days": float(gaps.median()), "by_month": {str(k): int(v) for k, v in months.items()},
         "by_weekday": {k: int(v) for k, v in weekdays.items()}},
        ["The export gives a publish date, not a time of day, so only the weekday can be examined."],
    )


def _comparison_details(c: Comparison) -> dict:
    return {k: (None if isinstance(v, float) and math.isnan(v) else v) for k, v in asdict(c).items()}


def formats(ctx: Context) -> Finding:
    """Shorts against long-form: do they perform differently on views?"""
    duration, views = _num(ctx.frame, DURATION), _num(ctx.frame, VIEWS)
    known = duration.notna() & views.notna()
    short = views[known & (duration <= SHORT_MAX_SECONDS)]
    long = views[known & (duration > SHORT_MAX_SECONDS)]
    c = compare(short, long)
    caveats = [
        f"Videos of {SHORT_MAX_SECONDS} seconds or less are treated as Shorts: the export does not say which videos "
        "are Shorts. Longer vertical Shorts are counted as long-form.",
        "Views are not adjusted for age here; a channel that posted Shorts more recently will look different.",
    ]
    if c.strength == "not_enough_data":
        return Finding("formats", "Shorts and long-form",
                       f"{c.n_a} Shorts and {c.n_b} long-form videos: too few of one kind to compare.",
                       "not_enough_data", _comparison_details(c), caveats)

    if c.strength == "weak" and c.p_value is not None and c.p_value >= 0.05:
        verdict = "No clear difference in views"
    else:
        verdict = "Shorts get more views" if c.ratio and c.ratio > 1 else "Long-form gets more views"
    headline = (
        f"{verdict}: Shorts have a median of {_fmt(c.median_a)} views ({c.n_a} videos) against {_fmt(c.median_b)} for "
        f"long-form ({c.n_b}), a ratio of {c.ratio:.2f} (95% range {c.ratio_low:.2f} to {c.ratio_high:.2f}), "
        f"p = {c.p_value:.3f}."
    )
    if c.strength == "weak" and min(c.n_a, c.n_b) < 10:
        caveats.append("Fewer than 10 videos in one group: treat this as a hint, not a result.")
    return Finding("formats", "Shorts and long-form", headline, c.strength, _comparison_details(c), caveats)


def click_through(ctx: Context) -> Finding:
    """Videos that were shown a lot but clicked less than is typical for the channel."""
    frame = ctx.frame.copy()
    frame["impressions"], frame["ctr"] = _num(frame, IMPRESSIONS), _num(frame, CTR)
    seen = frame.dropna(subset=["impressions", "ctr"])
    seen = seen[seen["impressions"] > 0]
    if len(seen) < MIN_VIDEOS:
        return Finding("click_through", "Click-through opportunities",
                       f"Needs at least {MIN_VIDEOS} videos with impressions; this export has {len(seen)}. "
                       "Videos without impressions (often Shorts) are left out, not counted as 0%.",
                       "not_enough_data")

    # Weighted by impressions: a mean of per-video rates would let a tiny video count as much as a huge one.
    typical = float((seen["ctr"] * seen["impressions"]).sum() / seen["impressions"].sum())
    low_ctr = seen["ctr"].quantile(0.25)
    big = seen["impressions"] >= seen["impressions"].median()
    flagged = seen[big & (seen["ctr"] <= low_ctr)].sort_values("impressions", ascending=False)
    rows = [
        _video(r, impressions=float(r["impressions"]), ctr=float(r["ctr"]), views=float(_num(frame, VIEWS)[i]))
        for i, r in flagged.head(5).iterrows()
    ]
    headline = (
        f"{len(flagged)} of {len(seen)} videos were shown to many people but clicked at or below the bottom quarter "
        f"({low_ctr:.1f}%) against a channel rate of {typical:.1f}%."
        if len(flagged) else
        f"No video was both widely shown and clicked unusually little (channel rate {typical:.1f}%)."
    )
    return Finding(
        "click_through", "Click-through opportunities", headline, "suggestive" if len(seen) >= 20 else "weak",
        {"channel_ctr": typical, "bottom_quarter_ctr": float(low_ctr), "videos_with_impressions": len(seen),
         "flagged": len(flagged), "candidates": rows},
        ["The channel rate is weighted by impressions, not an average of per-video rates.",
         "A low click rate on a widely shown video is a question about its title and thumbnail, not a verdict: "
         "browse and suggested traffic click less than search."],
    )


ANALYSES = (overview, performance, cadence, formats, click_through)


def run_audit(ctx: Context) -> list[Finding]:
    return [analysis(ctx) for analysis in ANALYSES]
